// Third-party data for the About screens (t32-e75; t32-cfg.md §4.11).
//
// third-party.json is generated by scripts/about/gen-third-party.mjs and committed:
// every shipped Rust crate (rust), the crates only in the Tauri apps (shells), the npm
// packages rollup bundled (web), fonts/icons/images (assets), the server images' own
// files (runtimeImage) and the build tools (buildTools). The licence texts are in
// texts/<0-f>.json, 16 shards by the first character of the text id (50-150 KB each),
// each its own chunk, loaded the first time a text in it is opened; the service worker
// keeps /assets/, so an opened text works offline after that. Everything is in the web
// bundle: nothing is fetched from the server API.

import listDoc from './third-party.json';

export const GROUPS = ['rust', 'shells', 'web', 'assets', 'runtimeImage', 'buildTools'] as const;
export type ThirdPartyGroup = (typeof GROUPS)[number];

export type ThirdPartyKind = 'crate' | 'npm' | 'font' | 'icons' | 'image' | 'os';
const KINDS: readonly ThirdPartyKind[] = ['crate', 'npm', 'font', 'icons', 'image', 'os'];

export interface LicenceTextRef {
  /** Key into the texts shards. */
  id: string;
  /** File name in the package, e.g. `LICENSE-MIT`, or an image path. */
  file?: string;
  /** Set instead of `file` when the package ships no licence file: the SPDX id
   *  whose standard text is shown. */
  standard?: string;
}

export interface ThirdPartyEntry {
  group: ThirdPartyGroup;
  kind: ThirdPartyKind;
  name: string;
  version?: string;
  /** SPDX expression as declared, e.g. `MIT OR Apache-2.0`; for a Debian package the
   *  `License:` names of its copyright file, or empty when that file has none. */
  licence: string;
  repository?: string;
  homepage?: string;
  texts: LicenceTextRef[];
  /** Crates: which parts use it (`server`, `web`, `plugins`, `desktop`, `mobile`). */
  artifacts?: string[];
  /** Image files: which server image holds it (`runtime`, `runtime-static`). */
  images?: string[];
  /** Assets and image files: `bundled`, `fonts-pull`, `first-party`, `static-libc`, `alpine-ca`. */
  note?: string;
}

/** An https link, or undefined; checked again before it becomes an href. */
export function safeHref(raw: unknown): string | undefined {
  if (typeof raw !== 'string') return undefined;
  try {
    const u = new URL(raw);
    return u.protocol === 'https:' && !u.username && !u.password ? u.href : undefined;
  } catch {
    return undefined;
  }
}

/** The licence ids in an SPDX expression, without operators, exceptions or `+`. */
export function licenceIdsOf(expr: string): string[] {
  const out: string[] = [];
  let afterWith = false;
  for (const tok of expr.match(/[^\s()]+/g) ?? []) {
    const up = tok.toUpperCase();
    if (up === 'WITH') {
      afterWith = true;
      continue;
    }
    if (up === 'OR' || up === 'AND') continue;
    if (afterWith) {
      afterWith = false;
      continue;
    }
    const id = tok.replace(/\+$/, '');
    if (!out.includes(id)) out.push(id);
  }
  return out;
}

function str(v: unknown): string | undefined {
  return typeof v === 'string' && v !== '' ? v : undefined;
}

function strings(v: unknown): string[] | undefined {
  return Array.isArray(v) ? v.filter((a): a is string => typeof a === 'string') : undefined;
}

function toEntry(raw: unknown, group: ThirdPartyGroup): ThirdPartyEntry | null {
  if (!raw || typeof raw !== 'object') return null;
  const r = raw as Record<string, unknown>;
  const name = str(r.name);
  const kind = KINDS.find((k) => k === r.kind);
  if (!name || !kind) return null;
  const texts = Array.isArray(r.texts)
    ? r.texts.flatMap((t): LicenceTextRef[] => {
        if (!t || typeof t !== 'object') return [];
        const o = t as Record<string, unknown>;
        const id = str(o.id);
        if (!id) return [];
        const ref: LicenceTextRef = { id };
        const file = str(o.file);
        const standard = str(o.standard);
        if (file) ref.file = file;
        if (standard) ref.standard = standard;
        return [ref];
      })
    : [];
  const e: ThirdPartyEntry = { group, kind, name, licence: str(r.licence) ?? '', texts };
  const version = str(r.version);
  const repository = safeHref(r.repository);
  const homepage = safeHref(r.homepage);
  const note = str(r.note);
  const artifacts = strings(r.artifacts);
  const images = strings(r.images);
  if (version) e.version = version;
  if (repository) e.repository = repository;
  if (homepage) e.homepage = homepage;
  if (note) e.note = note;
  if (artifacts) e.artifacts = artifacts;
  if (images) e.images = images;
  return e;
}

/** Every entry of a third-party document, tagged with its group, in group order. */
export function aboutEntries(doc: unknown = listDoc): ThirdPartyEntry[] {
  if (!doc || typeof doc !== 'object') return [];
  const d = doc as Record<string, unknown>;
  return GROUPS.flatMap((g) => {
    const list = d[g];
    return (Array.isArray(list) ? list : [])
      .map((raw) => toEntry(raw, g))
      .filter((e): e is ThirdPartyEntry => e !== null);
  });
}

const shardLoaders = import.meta.glob<{ default: Record<string, string> }>('./texts/*.json');
const shardPromises = new Map<string, Promise<Record<string, string>>>();

function loadShard(h: string): Promise<Record<string, string>> {
  let p = shardPromises.get(h);
  if (!p) {
    const loader = shardLoaders[`./texts/${h}.json`];
    p = loader
      ? loader().then(
          (m) => m.default,
          (err: unknown) => {
            shardPromises.delete(h); // a failed load can be retried
            throw err;
          },
        )
      : Promise.resolve({});
    shardPromises.set(h, p);
  }
  return p;
}

/** The licence texts with these ids (from the shards that hold them; each loaded once). */
export async function loadLicenceTexts(ids: readonly string[]): Promise<Record<string, string>> {
  const shards = [...new Set(ids.map((id) => id.charAt(0)))];
  const loaded = await Promise.all(shards.map(loadShard));
  const out: Record<string, string> = {};
  for (const id of ids) {
    const text = loaded[shards.indexOf(id.charAt(0))]?.[id];
    if (text !== undefined) out[id] = text;
  }
  return out;
}
